import math
R3=math.sqrt(3)
def hp(x,y): return (x+0.5*y, R3/2*y)
H=[(0,0),(-1,-1),(0,-2),(2,-2),(2,-1),(4,-2),(5,-1),(4,0),(3,0),(2,2),(0,3),(0,2),(-1,2)]
HAT=[hp(*p) for p in H]
def inside(P,q):
    c=False;n=len(P)
    for i in range(n):
        a,b=P[i],P[(i+1)%n]
        if (a[1]>q[1])!=(b[1]>q[1]):
            x=a[0]+(q[1]-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if x>q[0]: c=not c
    return c
# hex centres: lattice generated by hp(2,2) and hp(-2,4)? check distances
def kites_of_hex(c):
    cx,cy=c; ks=[]
    for k in range(6):
        a=math.radians(60*k)
        V=(cx+2*math.cos(a),cy+2*math.sin(a))
        M1=(cx+R3*math.cos(a-math.pi/6),cy+R3*math.sin(a-math.pi/6))
        M2=(cx+R3*math.cos(a+math.pi/6),cy+R3*math.sin(a+math.pi/6))
        cen=((cx+V[0]+M1[0]+M2[0])/4,(cy+V[1]+M1[1]+M2[1])/4)
        ks.append(cen)
    return ks
def hexcentres(N, origin=(0,0)):
    a=hp(2,2); b=hp(-2,4)
    out=[]
    for i in range(-N,N+1):
        for j in range(-N,N+1):
            out.append((origin[0]+i*a[0]+j*b[0],origin[1]+i*a[1]+j*b[1]))
    return out
if __name__=='__main__':
    for org in [(0,0),hp(1,0),hp(0,1),hp(1,1),hp(2,0),hp(-1,1)]:
        cnt=0
        for c in hexcentres(4,org):
            for q in kites_of_hex(c):
                if inside(HAT,q): cnt+=1
        print(org,cnt)
